// ── Projected ledger constants (from lg:LEDGER_CONSTANTS) ────────────


/// hard cap on account count in one LedgerState
pub const MAX_ACCOUNTS: usize = 65536;

/// state root width in bytes
pub const STATE_ROOT_LEN: usize = 32;

/// per-transition gas placeholder (0 = counted, never charged)
pub const TRANSITION_GAS: usize = 0;


use std::collections::{BTreeMap, BTreeSet};

/// 32-byte account identifier (S1 strata-hash digest width).
pub type AccountId = [u8; 32];

/// State-root width fixture: the projected STATE_ROOT_LEN.
pub type Root = [u8; STATE_ROOT_LEN as usize];

/// One account (ontology class st:Account).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Account {
    pub id: AccountId,
    pub balance: u128,
}

/// TxLike: minimal local tx shape this ledger consumes. S2-shaped after the
/// strata-tx-pack Tx (replay-guard nonce + inputs/outputs; provenance:
/// packs/strata-tx-pack/templates/tx_model.rs.tera, roadmap slice S2). This
/// is a documentation-only shape mirror — no cross-pack dependency
/// (FM-PACK-018).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TxLike {
    /// Per-account replay-guard nonce (strata-tx-pack TX nonce convention).
    pub nonce: u64,
    /// Consumed side: (account id, amount) pairs.
    pub inputs: Vec<(AccountId, u128)>,
    /// Produced side: (account id, amount) pairs.
    pub outputs: Vec<(AccountId, u128)>,
    /// 32-byte digest of the exact tx bytes (replay court key).
    pub digest: [u8; 32],
}

/// Refusal valve: the explicit refusal type mirroring the PN64/valve pattern
/// (roadmap S4: "double-spend refusal via valve"). Zero-denial-admitted
/// polarity: `admitted()` is true only for the zero case — there is no
/// Ok-with-reservations arm; every non-admission is a typed refusal.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LedgerRefusal {
    /// A per-account nonce was reused (double spend; also covers replay of
    /// the same nonce).
    DoubleSpend,
    /// The exact tx digest was already applied (replay).
    Replay,
    /// Amount arithmetic would overflow u128.
    Overflow,
    /// Sum(inputs) != sum(outputs): value would be created or destroyed.
    Conservation,
    /// Applying the transition would exceed MAX_ACCOUNTS.
    CapacityExceeded,
    /// A debit exceeded the account's balance.
    InsufficientFunds,
}

impl LedgerRefusal {
    /// Zero-denial-admitted polarity: refusals are nonzero by construction;
    /// the admitted (zero) case is `Ok(..)`, never a refusal value.
    pub fn code(&self) -> u64 {
        match *self {
            LedgerRefusal::DoubleSpend => 1,
            LedgerRefusal::Replay => 2,
            LedgerRefusal::Overflow => 3,
            LedgerRefusal::Conservation => 4,
            LedgerRefusal::CapacityExceeded => 5,
            LedgerRefusal::InsufficientFunds => 6,
        }
    }
}

/// Receipt of one applied transition (ontology class st:TransitionReceipt).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct StateTransitionReceipt {
    /// Monotonic transition index (st:transitionIndex).
    pub index: u64,
    /// State root before the commit (st:prevStateRoot).
    pub prev_root: Root,
    /// State root after the commit (st:stateRoot).
    pub next_root: Root,
    /// Digest of the committed tx (st:appliedTxDigest).
    pub applied_tx_digest: [u8; 32],
}

/// Account-based ledger state (ontology class st:LedgerState).
#[derive(Debug, Clone, Default)]
pub struct LedgerState {
    accounts: BTreeMap<AccountId, u128>,
    /// Last accepted nonce per (input) account.
    nonces: BTreeMap<AccountId, u64>,
    /// Applied tx digests (replay court).
    seen: BTreeSet<[u8; 32]>,
    root: Root,
    index: u64,
}

impl LedgerState {
    pub fn new() -> LedgerState {
        LedgerState {
            accounts: BTreeMap::new(),
            nonces: BTreeMap::new(),
            seen: BTreeSet::new(),
            root: [0u8; STATE_ROOT_LEN as usize],
            index: 0,
        }
    }

    /// Genesis allocation: pre-transition account seeding (documented
    /// genesis/airdrop surface, outside the transition law — the transition
    /// law itself never creates or destroys value). The genesis root becomes
    /// the base of the receipt chain.
    pub fn with_genesis(alloc: &[(AccountId, u128)]) -> LedgerState {
        let mut st = LedgerState::new();
        for &(id, bal) in alloc.iter() {
            st.accounts.insert(id, bal);
        }
        st.recompute_root();
        st
    }

    pub fn root(&self) -> Root {
        self.root
    }

    pub fn balance(&self, id: &AccountId) -> u128 {
        match self.accounts.get(id) {
            Some(b) => *b,
            None => 0,
        }
    }

    pub fn account_count(&self) -> usize {
        self.accounts.len()
    }

    pub fn index(&self) -> u64 {
        self.index
    }

    /// Deterministic placeholder state root (FNV-1a mixing over the sorted
    /// account set + index; strata-tx-pack placeholder convention until S1
    /// binds the real hash). Equal states derive equal roots.
    fn recompute_root(&mut self) {
        let mut h: u64 = 0xcbf29ce484222325;
        let mut mix = |b: u8, h: &mut u64| {
            *h = (*h ^ b as u64).wrapping_mul(0x100000001b3);
        };
        for (id, bal) in self.accounts.iter() {
            for i in 0..32 {
                mix(id[i], &mut h);
            }
            let mut b = *bal;
            let mut k = 0;
            while k < 16 {
                mix((b & 0xff) as u8, &mut h);
                b = b >> 8;
                k = k + 1;
            }
        }
        let mut idx = self.index;
        let mut k = 0;
        while k < 8 {
            mix((idx & 0xff) as u8, &mut h);
            idx = idx >> 8;
            k = k + 1;
        }
        let mut root = [0u8; STATE_ROOT_LEN as usize];
        let mut i = 0;
        while i < STATE_ROOT_LEN as usize {
            root[i] = ((h >> ((i % 8) * 8)) & 0xff) as u8;
            i = i + 1;
        }
        self.root = root;
    }

    /// Masked commit: apply one transition all-or-nothing. Every gate
    /// (replay, nonce, overflow, conservation, capacity, funds) runs BEFORE
    /// any balance mutates; on refusal the state is bit-identical to the
    /// input. On admission, receipts the prior root (receipt chaining).
    pub fn apply_transition(
        &mut self,
        tx: &TxLike,
    ) -> Result<StateTransitionReceipt, LedgerRefusal> {
        let prev_root = self.root;

        // Gate 1: replay valve.
        if self.seen.contains(&tx.digest) {
            return Err(LedgerRefusal::Replay);
        }

        // Gate 2: double-spend valve — every input account must advance its
        // nonce strictly (nonce reuse per account is refused).
        for &(id, _) in tx.inputs.iter() {
            let last = match self.nonces.get(&id) {
                Some(n) => *n,
                None => 0,
            };
            if tx.nonce == 0 || tx.nonce <= last {
                return Err(LedgerRefusal::DoubleSpend);
            }
        }

        // Gate 3: overflow + conservation over the masked sums.
        let mut sum_in: u128 = 0;
        for &(_, amt) in tx.inputs.iter() {
            sum_in = match sum_in.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        let mut sum_out: u128 = 0;
        for &(_, amt) in tx.outputs.iter() {
            sum_out = match sum_out.checked_add(amt) {
                Some(s) => s,
                None => return Err(LedgerRefusal::Overflow),
            };
        }
        if sum_in != sum_out {
            return Err(LedgerRefusal::Conservation);
        }

        // Gate 4: funds + capacity, checked against a shadow copy (masked:
        // nothing here mutates self).
        let mut shadow: BTreeMap<AccountId, u128> = BTreeMap::new();
        for &(id, amt) in tx.inputs.iter() {
            let cur = self.balance(&id);
            if cur < amt {
                return Err(LedgerRefusal::InsufficientFunds);
            }
            shadow.insert(id, cur - amt);
        }
        for &(id, amt) in tx.outputs.iter() {
            let cur = match shadow.get(&id) {
                Some(b) => *b,
                None => self.balance(&id),
            };
            let next = match cur.checked_add(amt) {
                Some(v) => v,
                None => return Err(LedgerRefusal::Overflow),
            };
            shadow.insert(id, next);
        }
        let mut new_accounts = 0usize;
        for &id in shadow.keys() {
            if !self.accounts.contains_key(&id) {
                new_accounts = new_accounts + 1;
            }
        }
        if self.accounts.len() + new_accounts > MAX_ACCOUNTS as usize {
            return Err(LedgerRefusal::CapacityExceeded);
        }

        // ── Commit (masked: reached only when every gate passed) ────────
        for (id, bal) in shadow.into_iter() {
            if bal == 0 && tx.outputs.iter().find(|&&(oid, _)| oid == id).is_none() {
                self.accounts.remove(&id);
            } else {
                self.accounts.insert(id, bal);
            }
        }
        for &(id, _) in tx.inputs.iter() {
            self.nonces.insert(id, tx.nonce);
        }
        self.seen.insert(tx.digest);
        self.index = self.index + 1;
        self.recompute_root();

        Ok(StateTransitionReceipt {
            index: self.index,
            prev_root: prev_root,
            next_root: self.root,
            applied_tx_digest: tx.digest,
        })
    }

    /// Receipt-chain law (unibit verify_receipt_chain projection): each
    /// receipt's prev_root must equal the prior state root it replaced —
    /// i.e. receipt[i].prev_root == receipt[i-1].next_root, receipt[0]
    /// .prev_root == the genesis root, and index strictly increases.
    pub fn verify_receipt_chain(
        genesis_root: &Root,
        receipts: &[StateTransitionReceipt],
    ) -> bool {
        let mut prev = *genesis_root;
        let mut last_index: u64 = 0;
        let mut first = true;
        for rc in receipts.iter() {
            if rc.prev_root != prev {
                return false;
            }
            if !first && rc.index <= last_index {
                return false;
            }
            first = false;
            last_index = rc.index;
            prev = rc.next_root;
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn id(n: u8) -> AccountId {
        let mut a = [0u8; 32];
        a[0] = n;
        a
    }

    fn mk_tx(nonce: u64, digest: [u8; 32], ios: &[(AccountId, u128, u128)]) -> TxLike {
        let mut inputs = Vec::new();
        let mut outputs = Vec::new();
        for &(acct, amt_in, amt_out) in ios.iter() {
            if amt_in > 0 {
                inputs.push((acct, amt_in));
            }
            if amt_out > 0 {
                outputs.push((acct, amt_out));
            }
        }
        TxLike {
            nonce: nonce,
            inputs: inputs,
            outputs: outputs,
            digest: digest,
        }
    }

    #[test]
    fn conservation_holds_over_random_sequences() {
        // Deterministic LCG "random" sequence of conservation-preserving
        // transfers; total supply must be invariant after every commit.
        let mut seed: u64 = 0x243F6A8885A308D3;
        let a = id(1);
        let b = id(2);
        let c = id(3);
        // Genesis allocation (pre-transition; the transition law never
        // creates value).
        let mut st = LedgerState::with_genesis(&[
            (a, 1_000_000u128),
            (b, 400_000u128),
            (c, 600_000u128),
        ]);
        let genesis_root = st.root();
        let mut receipts = Vec::new();
        let supply = 2_000_000u128;
        let mut n = 0;
        while n < 200 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let from = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let to = match (seed >> 33) % 3 {
                0 => a,
                1 => b,
                _ => c,
            };
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let amt: u128 = (((seed >> 20) % 5_000) + 1) as u128;
            if from == to {
                continue;
            }
            if st.balance(&from) < amt {
                continue;
            }
            let mut d = [0u8; 32];
            d[0] = 7;
            let base: [u8; 8] = [
                (n & 0xff) as u8,
                ((n >> 8) & 0xff) as u8,
                0, 0, 0, 0, 0, 0,
            ];
            let mut i = 0;
            while i < 8 {
                d[1 + i] = base[i];
                i = i + 1;
            }
            let tx = mk_tx(1000 + n as u64, d, &[(from, amt, 0), (to, 0, amt)]);
            let rc = st.apply_transition(&tx).ok().unwrap();
            receipts.push(rc);
            let total = st.balance(&a) + st.balance(&b) + st.balance(&c);
            assert_eq!(total, supply);
            n = n + 1;
        }
        assert!(LedgerState::verify_receipt_chain(&genesis_root, &receipts));
    }

    #[test]
    fn double_spend_refused() {
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000u128)]);
        let a = id(1);
        let b = id(2);
        assert!(st.apply_transition(&mk_tx(5, [1u8; 32], &[(a, 500u128, 0), (b, 0, 500)])).is_ok());
        // Reuse account A's nonce 5 → DoubleSpend, state untouched.
        let r = st.apply_transition(&mk_tx(5, [2u8; 32], &[(a, 500u128, 0), (b, 0, 500)]));
        assert_eq!(r, Err(LedgerRefusal::DoubleSpend));
        // Nonce must strictly advance: going backwards also refuses.
        let r2 = st.apply_transition(&mk_tx(3, [3u8; 32], &[(a, 500u128, 0), (b, 0, 500)]));
        assert_eq!(r2, Err(LedgerRefusal::DoubleSpend));
        // Refusal is masked: state bit-identical (a=500, b=500 unchanged).
        assert_eq!(st.balance(&a), 500);
        assert_eq!(st.balance(&b), 500);
    }

    #[test]
    fn overflow_refused() {
        let mut st = LedgerState::with_genesis(&[
            (id(2), u128::MAX - 9u128),
            (id(3), 10u128),
        ]);
        let a = id(1);
        let b = id(2);
        let c = id(3);
        // B (MAX-10) + 10 credits C's 10 via a transfer that routes through B.
        let r = st.apply_transition(&mk_tx(2, [2u8; 32], &[
            (c, 10u128, 0),
            (b, 0, 10),
        ]));
        // B receives 10 while holding MAX-10 → output-side overflow.
        assert_eq!(r, Err(LedgerRefusal::Overflow));
    }

    #[test]
    fn replay_refused() {
        let mut st = LedgerState::with_genesis(&[(id(1), 100u128)]);
        let a = id(1);
        let b = id(2);
        let tx = mk_tx(1, [4u8; 32], &[(a, 100u128, 0), (b, 0, 100)]);
        assert!(st.apply_transition(&tx).is_ok());
        // Byte-identical tx re-submitted (fresh state copy semantics would
        // admit it; the seen-digest valve refuses).
        let r = st.apply_transition(&tx);
        assert_eq!(r, Err(LedgerRefusal::Replay));
    }

    #[test]
    fn receipt_chain_verifies() {
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000_000u128)]);
        let genesis = st.root();
        let a = id(1);
        let b = id(2);
        let mut receipts = Vec::new();
        let mut n = 0u64;
        while n < 10 {
            let mut d = [0u8; 32];
            d[0] = 8;
            d[1] = n as u8;
            let tx = mk_tx(
                n + 1,
                d,
                &[(a, (n as u128 + 1u128) * 100u128, 0), (b, 0, (n as u128 + 1u128) * 100u128)],
            );
            receipts.push(st.apply_transition(&tx).ok().unwrap());
            n = n + 1;
        }
        // Chaining law: each receipt's prev_root == prior state root.
        assert!(LedgerState::verify_receipt_chain(&genesis, &receipts));
        // Negative witness: a corrupted receipt breaks the chain.
        let mut broken = receipts.clone();
        broken[3].prev_root = [9u8; STATE_ROOT_LEN as usize];
        assert!(!LedgerState::verify_receipt_chain(&genesis, &broken));
        // Positive control: empty chain over genesis trivially verifies.
        assert!(LedgerState::verify_receipt_chain(&genesis, &[]));
    }

    #[test]
    fn conservation_refusal_masks_state() {
        // Value creation is refused and the state is bit-identical after.
        let mut st = LedgerState::with_genesis(&[(id(1), 1_000u128), (id(2), 1_000u128)]);
        let a = id(1);
        let b = id(2);
        let root_before = st.root();
        // Outputs create 1 unit out of nothing.
        let r = st.apply_transition(&mk_tx(2, [2u8; 32], &[
            (a, 1_000u128, 0),
            (b, 0, 1_001),
        ]));
        assert_eq!(r, Err(LedgerRefusal::Conservation));
        assert_eq!(st.root(), root_before);
        // The valid successor still lands with the correct chaining shape.
        let ok = st.apply_transition(&mk_tx(2, [3u8; 32], &[
            (a, 1_000u128, 0),
            (b, 0, 1_000),
        ])).ok().unwrap();
        assert_eq!(ok.prev_root, root_before);
    }
}
